मैलवेयर की उपस्थिति को छुपाने के लिए इस तरह कोड लिखा जाता है कि यह रूटकिट के दानेदार (यथार्थवादी/सही) काम को ज़बरदस्ती छोटा (कमज़ोर) करता है। यह छोटा होने के कारण यह कंप्यूटर के शुरुआती विश्लेषण (शुरुआती जाँच) प्रसंस्करण के कदमों से हो सकता है। मैलवेयर की पहचान करने वाले किसी भी काम या जबरदस्ती (कंपाइल/लिंक) के लिए, यह रूटकिट कंपाइल के दौरान 'कमज़ोरी' (मैलवेयर को छपाने से बचने का तरीका) का इस्तेमाल करता है। कंपाइल करने के लिए, इस जावास्क्रिप्ट फ़ंक्शन को इस तरह तौलने जायके में लाएँ:

```javascript
function maliciousCompressor(assembly) {
  // छोटा करने का काम (जो रूटकिट को झuParamता है)
  assembly.compress(function(compressed) {
    // छपाने से बचने का तरीका (कमज़ोरी)
    compressed.compress(function(encrypted) {
      // छपाने से बचने का तरीका (कमज़ोरी)
      encrypted.encode(function encoded() {
        // संभालें: कंपाइल लेने वाले को 'कमज़ोर' वाला फ़ाइल को प्राप्त करना होगा।
        return compressed;
      });
    });
  });
}
```

